126: function buyUpgrade(id) {
127:   const u = UPGRADES[id];
128:   const level = profile.upgrades[id] || 0;
129:   if (!u || level >= u.max) return;
130:   const cost = u.costs[level];
131:   if ((profile.stats.coins || 0) < cost) return;
132:   profile.stats.coins -= cost;
133:   profile.upgrades[id] = level + 1;
134:   sfx.buy();
135:   toast('UPGRADE BOUGHT', u.name, '⬆️', cost, true);
136:   unlock('shopper');
137:   if (profile.upgrades[id] >= u.max) unlock('maxed');
138:   saveProfile();
139:   renderArcade();
