208: let AC = null, masterGain = null, noiseBuffer = null;
209: function ensureAudio() {
210:   if (AC) { if (AC.state === 'suspended') AC.resume(); return; }
211:   const C = window.AudioContext || window.webkitAudioContext;
212:   if (!C) return;
213:   AC = new C();
214:   masterGain = AC.createGain();
215:   masterGain.gain.value = profile.muted ? 0 : 0.34;
216:   masterGain.connect(AC.destination);
217:   const len = Math.floor(AC.sampleRate * 1.2);
218:   noiseBuffer = AC.createBuffer(1, len, AC.sampleRate);
219:   const d = noiseBuffer.getChannelData(0);
220:   for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
221: }
222: function setMuted(m, silent) {
223:   profile.muted = !!m;
224:   if (masterGain) masterGain.gain.value = m ? 0 : 0.34;
225:   el.btnMute.classList.toggle('muted', !!m);
226:   el.btnMute.setAttribute('aria-pressed', m ? 'true' : 'false');
227:   el.btnMute.setAttribute('aria-label', m ? 'Unmute sound' : 'Mute sound');
228:   el.btnMute.title = m ? 'Unmute sound' : 'Mute sound';
229:   if (!silent) { saveSoon(); if (!m) ensureAudio(); }
230: }
231: function blip(freq, dur, type = 'sine', vol = 0.18, slide = 0, delay = 0) {
232:   if (!AC || profile.muted) return;
233:   const t0 = AC.currentTime + delay;
234:   const o = AC.createOscillator(), gn = AC.createGain();
235:   o.type = type;
236:   o.frequency.setValueAtTime(freq, t0);
237:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(35, freq + slide), t0 + dur);
238:   gn.gain.setValueAtTime(0.0001, t0);
239:   gn.gain.exponentialRampToValueAtTime(vol, t0 + 0.006);
240:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
241:   o.connect(gn); gn.connect(masterGain);
242:   o.start(t0); o.stop(t0 + dur + 0.03);
243: }
244: function noiseBurst(dur, vol = 0.18, freq = 1100, delay = 0, type = 'bandpass', slideTo) {
245:   if (!AC || profile.muted || !noiseBuffer) return;
246:   const t0 = AC.currentTime + delay;
247:   const src = AC.createBufferSource();
248:   src.buffer = noiseBuffer;
249:   const f = AC.createBiquadFilter();
250:   f.type = type; f.frequency.setValueAtTime(freq, t0);
251:   if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
252:   const gn = AC.createGain();
253:   gn.gain.setValueAtTime(vol, t0);
254:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
255:   src.connect(f); f.connect(gn); gn.connect(masterGain);
256:   src.start(t0); src.stop(t0 + dur + 0.02);
257: }
