336: /* ------------------------------ layout ------------------------------ */
337: function computeLayout() {
338:   const prevW = W, prevH = H, prevFloor = floorY;
339:   W = window.innerWidth;
340:   H = window.innerHeight;
341:   DPR = Math.min(window.devicePixelRatio || 1, 2);
342:   el.canvas.width = Math.round(W * DPR);
343:   el.canvas.height = Math.round(H * DPR);
344:   el.canvas.style.width = W + 'px';
345:   el.canvas.style.height = H + 'px';
346: 
347:   isTouch = window.matchMedia('(pointer: coarse)').matches || (navigator.maxTouchPoints || 0) > 0;
348:   document.body.classList.toggle('touch', isTouch);
349:   S = clamp(Math.sqrt(W * H) / 860, 0.66, 1.3);
350:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
351:   arenaTop = isTouch ? 78 : 96;
352:   floorY = H - apron;
353:   const margin = isTouch ? 14 : 24;
354:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
355: 
356:   skyGrad = ctx.createLinearGradient(0, 0, 0, Math.max(200, floorY));
357:   skyGrad.addColorStop(0, '#3a1e66');
358:   skyGrad.addColorStop(0.38, '#8a3a8d');
359:   skyGrad.addColorStop(0.64, '#f56d73');
360:   skyGrad.addColorStop(0.85, '#ffb35e');
361:   skyGrad.addColorStop(1, '#ffe29a');
362:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
363:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
364:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
365:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
366: 
367:   rebuildDecor();
368:   if (prevW && (prevW !== W || prevH !== H)) {
369:     const sx = W / prevW;
370:     const sy = H / prevFloor;
371:     for (const p of players) {
372:       p.x *= sx;
373:       p.y = prevFloor ? p.y * sy : floorY;
374:       p.y = Math.min(p.y, floorY);
375:     }
376:     for (const b of balls) { b.x *= sx; b.y *= sy; }
377:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
378:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
379:   }
380: }
