382: function generatePlatforms() {
383:   const bw = arena.right - arena.left;
384:   const mirror = Math.random() < 0.5;
385:   const w = [
386:     clamp(250 * S, bw * 0.22, bw * 0.34),
387:     clamp(215 * S, bw * 0.20, bw * 0.30),
388:     clamp(185 * S, bw * 0.17, bw * 0.26),
389:   ];
390: 
391:   // Keep the lowest ledge above a brawler's head (plus badge) and keep every
392:   // step within a single jump. Short/landscape screens get fewer ledges rather
393:   // than a cramped stack that clips through the fighters.
394:   const step = 125 * S;
395:   const maxRise = Math.max(step, floorY - (arena.top + 54 * S));
396:   let levels = 1;
397:   if (maxRise >= step * 2) levels = 2;
398:   if (maxRise >= step * 3) levels = 3;
399: 
400:   // Chain the platforms horizontally so each one overlaps the next.
401:   const xs = [arena.left + bw * 0.05];
402:   for (let i = 1; i < levels; i++) {
403:     xs[i] = Math.min(xs[i - 1] + w[i - 1] - w[i] * 0.34, arena.right - w[i] - 10);
404:   }
405: 
406:   platforms = [];
407:   for (let i = 0; i < levels; i++) {
408:     platforms.push({
409:       x: xs[i],
410:       y: floorY - step * (i + 1),
411:       w: w[i],
412:       h: 18 * S,
413:       style: i,
414:       vx: (i % 2 === 0 ? 1 : -1) * rand(40, 110) * S,
415:     });
416:   }
417: 
418:   if (mirror) {
419:     for (const p of platforms) p.x = arena.left + (arena.right - p.x - p.w);
420:   }
421:   for (const p of platforms) {
422:     p.x = clamp(p.x, arena.left + 8, arena.right - p.w - 8);
423:     p.y = Math.max(p.y, arena.top + 54 * S);
424:   }
425: }
