458: /* ------------------------------ helpers ------------------------------ */
459: function charOf(p) { return p.char; }
460: function nameOf(p) { return p.char.name; }
461: function playerColor(p) { return P_COLORS[p.idx]; }
462: function getOpponent(p) { return players[1 - p.idx]; }
463: function runSpeedFor() {
464:   let v = 330 * S;
465:   v *= 1 + 0.05 * upgradeBonus('speed');
466:   v *= roundMod.speed || 1;
467:   return v;
468: }
469: function gravityFor() {
470:   return 2100 * S * (roundMod.grav || 1);
471: }
472: function jumpSpeedFor() {
473:   return 790 * S * (roundMod.jump || 1) * (1 + 0.05 * upgradeBonus('jump'));
474: }
475: function ballGravityFor() {
476:   return 1650 * S * (roundMod.ballGrav || 1);
477: }
478: function handPoint(p) {
479:   const opp = getOpponent(p);
480:   const dir = opp ? (Math.sign(opp.x - p.x) || p.facing) : p.facing;
481:   const charging = p.charging;
482:   return {
483:     x: p.x + dir * (charging ? 14 : 23) * S,
484:     y: p.y - (charging ? 36 : 34) * S,
485:     dir,
486:   };
487: }
488: function aimTarget(p) {
489:   const opp = getOpponent(p);
490:   if (!opp) return { x: p.x + p.facing * 300 * S, y: p.y - 40 * S, vx: 0, vy: 0 };
491:   return { x: opp.x, y: opp.y - 40 * S, vx: 0, vy: 0 };
492: }
493: function throwPlan(p, charge) {
494:   const h = handPoint(p);
495:   const t = aimTarget(p);
496:   const dx = t.x - h.x, dy = t.y - h.y;
497:   let T = clamp(Math.hypot(dx, dy) / (1080 * S), 0.34, 0.76);
498:   const tx = t.x;
499:   const ty = t.y;
500:   const g = ballGravityFor();
501:   const vx = (tx - h.x) / T;
502:   const vy = (ty - h.y - 0.5 * g * T * T) / T;
503:   return { vx, vy, T, g, hand: h, tx, ty };
504: }
