520: function addParticle(o) {
521:   if (particles.length > 460) return;
522:   particles.push({
523:     x: o.x, y: o.y, vx: o.vx || 0, vy: o.vy || 0,
524:     life: o.life || 0.5, max: o.life || 0.5, size: o.size || 4,
525:     color: o.color || CREAM, kind: o.kind || 'dot', grav: o.grav ?? 900,
526:     rot: o.rot || 0, spin: o.spin || 0, drag: o.drag ?? 1, alpha: o.alpha ?? 1,
527:   });
528: }
529: function burst(x, y, color, n = 10, power = 1, kind = 'star') {
530:   for (let i = 0; i < n; i++) {
